const recent = $json.filings?.recent;
if (!recent?.accessionNumber) throw new Error('SEC submissions response is missing recent filings');
const baselineDate = '2026-08-04';
const allowedForms = new Set(['10-K', '10-Q', '8-K']);
const detectedAt = new Date().toISOString();
return recent.accessionNumber.map((accession, i) => {
  const form = recent.form[i];
  const filingDate = recent.filingDate[i];
  const reportDate = recent.reportDate[i] || null;
  const primaryDocument = recent.primaryDocument[i];
  const sourceUri = `https://www.sec.gov/Archives/edgar/data/80420/${accession.replaceAll('-', '')}/${primaryDocument}`;
  const packetMaterial = JSON.stringify({cik:'0000080420',accession,form,filingDate,reportDate,primaryDocument,sourceUri});
  return {accession,form,filingDate,reportDate,primaryDocument,sourceUri,packetMaterial};
}).filter(r => allowedForms.has(r.form) && r.filingDate > baselineDate).map(r => ({json:{
  source_uri:r.sourceUri,
  source_title:`Powell Industries ${r.form} filed ${r.filingDate}`,
  source_published_at:r.filingDate,
  retrieved_at:detectedAt,
  packet_material:r.packetMaterial,
  factual_summary:`SEC submissions metadata reports a Powell Industries ${r.form} filing dated ${r.filingDate}${r.reportDate ? ` for report date ${r.reportDate}` : ''}.`,
  interpretation_note:'Candidate filing detected. Filing content, map relevance, thesis impact, risks, and next proof point require human review.',
  limitations:'Metadata-only automated intake. The SHA-256 identifies the retained metadata packet, not the filing body. No map conclusion, lane approval, position size, or trade is implied.',
  dedupe_key:`sec:0000080420:${r.accession.toLowerCase()}:${r.form.toLowerCase()}`
}}));
